package android.graphics;public class Path{public final StringBuilder d=new StringBuilder();public Path(){}public void reset(){d.setLength(0);}public void moveTo(float x,float y){d.append("M ").append(x).append(' ').append(y).append(' ');}public void lineTo(float x,float y){d.append("L ").append(x).append(' ').append(y).append(' ');}public void cubicTo(float a,float b,float c,float e,float f,float g){d.append("C ").append(a).append(' ').append(b).append(' ').append(c).append(' ').append(e).append(' ').append(f).append(' ').append(g).append(' ');}public void close(){d.append("Z ");}}
